insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_applicant','applicant','noun','a person who makes a formal request for a job, a place on a course or a permit','[{"senseId":"applicant_1","meaning":"a person who makes a formal request for a job, a place on a course or a permit","acceptedParaphrases":["person who asks formally for a job","someone who makes a formal request for a place"],"masteryContexts":[{"contextId":"u7_01_applicant_meaning","text":"Each applicant must complete the online form and upload a recent photograph before Friday.","meaning":"a person who formally asks for a place or job","wrongMeanings":["a person who checks forms for mistakes","a person who is already working for the firm","a person who teaches a course in the evenings"]},{"contextId":"u7_01_applicant_paraphrase","text":"The college rejected the first applicant because the form had been completed in pencil.","meaning":"a person who has formally asked for a place","wrongMeanings":["a person who has already finished the course","a person who teaches on the engineering course","a person who is paid to test new machines"]}],"situationDistractors":["A girl sent in a letter and a CV asking for a summer job at the library.","A boy filled in a form to ask for a place at a sailing club.","A woman wrote to the council to ask for a parking permit.","The cleaner locked the office and switched off all the lights.","Two students carried a heavy box of books up the stairs.","The receptionist watered the plants beside the main entrance."],"gapDistractors":[{"contextId":"u7_01_applicant_gap_1","answer":"applicant","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_01_applicant_gap_2","answer":"applicant","wrong":["passenger","neighbour","umbrella"]},{"contextId":"u7_01_applicant_gap_3","answer":"applicant","wrong":["museum","engine","meadow"]}],"spellingErrors":["aplicant","applikant","applicent","appplicant","applicnat","aplicent"],"wordFamilyForms":[{"form":"applicant","partOfSpeech":"noun","example":"The company will contact every applicant before the end of the month.","pedagogicallyUseful":true},{"form":"application","partOfSpeech":"noun","example":"Her application included a letter, a CV and the names of two referees.","pedagogicallyUseful":true,"altExample":"The school received a strong application from a young teacher who had just qualified."},{"form":"apply","partOfSpeech":"verb","example":"Students who want to study abroad must apply before the end of January.","pedagogicallyUseful":true,"altExample":"Anyone aged sixteen or over can apply for the weekend job."}],"masteryPassages":[{"passageId":"u7_01_applicant_passage_1","contextId":"u7_01_applicant_gap_1","text":"The supermarket advertised one evening job for students. By the closing date, more than fifty people had written in, and the manager had to read every letter carefully to find the best ____.","answer":"applicant"},{"passageId":"u7_01_applicant_passage_2","contextId":"u7_01_applicant_gap_2","text":"Before the college could offer any places, it had to check every form. Each ____ had to give two references and list the exams they had taken.","answer":"applicant"}],"contextDependentParaphrases":[],"wrongParaphrases":["person who checks forms","person who trains new staff","person who is offered a job"],"misleadingDistractors":["a person who is offered a job after an interview","a person who checks forms before they are sent out","a person who trains new members of staff"],"teacherNote":"Noun: a person who formally asks for a job, a course place or a permit, usually in writing. Boundary: an applicant has only asked; a candidate is a person who is being considered or has been shortlisted. The verb apply and the noun application are taught in the Word Family pathway."}]'::jsonb,'["application","apply"]'::jsonb,'["a successful applicant","a job applicant","an applicant for a place"]'::jsonb,'live'),
('vocab_qualifications','qualifications','noun','the exam results, degrees and training that show a person is suitable for a job or course','[{"senseId":"qualifications_1","meaning":"the exam results, degrees and training that show a person is suitable for a job or course","acceptedParaphrases":["exam results and training you have completed","official proof of what you have studied"],"masteryContexts":[{"contextId":"u7_02_qualifications_meaning","text":"Applicants with good qualifications in science are welcome to apply for the laboratory post.","meaning":"exam results and training that show suitability","wrongMeanings":["personal opinions about science and its history","equipment needed to work in a laboratory","promises made to other workers in a laboratory"]},{"contextId":"u7_02_qualifications_paraphrase","text":"On his CV, Omar listed his qualifications first, because the job required a degree in engineering.","meaning":"degrees and training listed as proof of ability","wrongMeanings":["hobbies and interests listed to fill space","addresses of people who could recommend him","dates when he had visited other countries"]}],"situationDistractors":["A woman handed over her degree certificate and her diploma at the start of the interview.","A man wrote a list of his exam results and courses at the top of his CV.","A girl proudly showed the panel her first-aid and lifesaving awards.","The driver parked the minibus beside the school gates.","A cat slept on the sofa while the rain fell outside.","The chef tasted the soup and added a little more salt."],"gapDistractors":[{"contextId":"u7_02_qualifications_gap_1","answer":"qualifications","wrong":["neighbours","journeys","bicycles"]},{"contextId":"u7_02_qualifications_gap_2","answer":"qualifications","wrong":["holidays","invitations","sandwiches"]},{"contextId":"u7_02_qualifications_gap_3","answer":"qualifications","wrong":["furniture","weather","souvenirs"]}],"spellingErrors":["qualificasions","qualifacations","qualificatons","qualifcations","qualificashions","qualifficatiosn"],"masteryPassages":[{"passageId":"u7_02_qualifications_passage_1","contextId":"u7_02_qualifications_gap_1","text":"The advertisement said that no experience was needed, but it listed a degree in design as essential. Zara had worked in the field for years, yet she was not invited because she lacked the right ____.","answer":"qualifications"},{"passageId":"u7_02_qualifications_passage_2","contextId":"u7_02_qualifications_gap_2","text":"When the interviewer read Karim’s CV, she noticed his exam results, his diplomas and his courses in first aid. His ____ were impressive for someone who had only just left school.","answer":"qualifications"}],"contextDependentParaphrases":[],"wrongParaphrases":["personal qualities that make someone popular","questions that an employer asks in a meeting","rules that workers must follow in a company"],"misleadingDistractors":["the personal qualities that make someone popular at work","the questions that an employer asks in an interview","the rules that workers must follow in a company"],"teacherNote":"Plural noun: the exam results, degrees, diplomas and training that show you are suitable for a job or a course (list your qualifications on a CV). It is always plural in this item. The singular qualification is a separate target in this unit: there it means a quality or skill that makes someone suitable, so do not use the two interchangeably."}]'::jsonb,'[]'::jsonb,'["academic qualifications","formal qualifications","the right qualifications for the job"]'::jsonb,'live'),
('vocab_demonstrate','demonstrate','verb','to show clearly that you have a skill, quality or piece of knowledge','[{"senseId":"demonstrate_1","meaning":"to show clearly that you have a skill, quality or piece of knowledge","acceptedParaphrases":["show clearly that you can","prove by showing in practice"],"masteryContexts":[{"contextId":"u7_03_demonstrate_meaning","text":"Good applicants demonstrate their interest in a job by asking questions about the company.","meaning":"to show clearly a quality or skill","wrongMeanings":["to hide a quality or skill from others","to teach a quality or skill to others","to forget a quality or skill after a short time"]},{"contextId":"u7_03_demonstrate_paraphrase","text":"She used a short story about leading a school project to demonstrate that she could manage people.","meaning":"to prove something by giving clear evidence","wrongMeanings":["to promise something without giving any evidence","to copy something that another person did","to complain about something that went wrong"]}],"situationDistractors":["A girl explained how she had raised money for charity and showed the photographs and the final total.","A boy used a short role-play to show the panel exactly how he would welcome a customer.","An applicant brought a folder of her own drawings to prove her skill as a designer.","The panel drank tea while they waited for the next person to arrive.","The candidate looked at the clock and wondered what to have for lunch.","A teacher wrote the names of the students on the register."],"gapDistractors":[{"contextId":"u7_03_demonstrate_gap_1","answer":"demonstrate","wrong":["forget","borrow","ignore"]},{"contextId":"u7_03_demonstrate_gap_2","answer":"demonstrate","wrong":["prevent","invent","cancel"]},{"contextId":"u7_03_demonstrate_gap_3","answer":"demonstrate","wrong":["hide","refuse","delay"]}],"spellingErrors":["demonstrait","demostrate","demonstrat","demonstate","demmonstrate","demonstreit"],"masteryPassages":[{"passageId":"u7_03_demonstrate_passage_1","contextId":"u7_03_demonstrate_gap_1","text":"The interviewer did not want to hear that Lena was a team player. She wanted her to ____ it with a real example, so Lena described how she had organised a charity match with ten classmates.","answer":"demonstrate"},{"passageId":"u7_03_demonstrate_passage_2","contextId":"u7_03_demonstrate_gap_2","text":"Many applicants say that they are hard-working, but few can prove it. The best way to ____ this quality is to describe a time when you worked hard and achieved a result.","answer":"demonstrate"}],"contextDependentParaphrases":[],"wrongParaphrases":["to hide clearly","to describe only in words","to repeat exactly from memory"],"misleadingDistractors":["to describe a skill without ever using it","to hide a weakness from other people","to ask someone else to prove a skill"],"teacherNote":"Verb: to show clearly, by what you say or do, that you have a skill, quality or piece of knowledge. In the interview context the usual pattern is demonstrate that / demonstrate how. Boundary: demonstrate involves showing, not only saying; the noun and the sense of protesting in a street are not taught here."}]'::jsonb,'[]'::jsonb,'["demonstrate a skill","demonstrate your ability","clearly demonstrate"]'::jsonb,'live'),
('vocab_summary','summary','noun','a short account that gives only the main points of something longer','[{"senseId":"summary_1","meaning":"a short account that gives only the main points of something longer","acceptedParaphrases":["short account of the main points","brief version of something longer"],"masteryContexts":[{"contextId":"u7_04_summary_meaning","text":"The teacher asked the class to write a summary of the story in no more than fifty words.","meaning":"a short account of the main points","wrongMeanings":["a long retelling of every single event","a private opinion about the main character","a list of new words from the story"]},{"contextId":"u7_04_summary_paraphrase","text":"At the top of her CV, Mia included a three-line summary of her skills and experience.","meaning":"a short statement of the key points","wrongMeanings":["a long explanation of how to write a CV","a list of the jobs she had refused","a full diary of her working week"]}],"situationDistractors":["A student read a long article and then wrote five sentences with only the key facts.","A manager told the team the three main results of a long report in one minute.","A girl gave a one-paragraph version of a chapter that was ten pages long.","The cook washed the vegetables and put them in a large bowl.","A taxi stopped outside the hotel and the driver opened the boot.","Two friends argued about which film to watch on Saturday night."],"gapDistractors":[{"contextId":"u7_04_summary_gap_1","answer":"summary","wrong":["recipe","invitation","souvenir"]},{"contextId":"u7_04_summary_gap_2","answer":"summary","wrong":["holiday","sandwich","neighbour"]},{"contextId":"u7_04_summary_gap_3","answer":"summary","wrong":["carpet","staircase","bicycle"]}],"spellingErrors":["sumary","summery","summmary","sumarry","summarry","sumery"],"masteryPassages":[{"passageId":"u7_04_summary_passage_1","contextId":"u7_04_summary_gap_1","text":"Nobody had time to read the forty-page report. The director asked Rania for a one-page ____, so she wrote down the three most important findings and the actions needed.","answer":"summary"},{"passageId":"u7_04_summary_passage_2","contextId":"u7_04_summary_gap_2","text":"The examiner told the class not to retell every event in the novel. A good ____, she said, uses only a few sentences and includes the main ideas.","answer":"summary"}],"contextDependentParaphrases":[],"wrongParaphrases":["long account of every detail","list of unanswered questions","personal opinion about a text"],"misleadingDistractors":["a long account that includes every small detail","a list of questions that nobody has answered","a personal opinion about a piece of writing"],"teacherNote":"Noun: a short account that gives only the main points of something longer (write a summary of, a brief summary). The verb summarise is a Unit 6 target and is not repeated here. Boundary: a summary is shorter than the original and contains no new opinion; an overview (also in this unit) is a general first look rather than a shortened copy."}]'::jsonb,'[]'::jsonb,'["a brief summary","write a summary","a summary of the main points"]'::jsonb,'live'),
('vocab_combine','combine','verb','to join two or more things, skills or qualities together','[{"senseId":"combine_1","meaning":"to join two or more things, skills or qualities together","acceptedParaphrases":["join together","put two or more things together"],"masteryContexts":[{"contextId":"u7_05_combine_meaning","text":"Many students combine part-time work with their studies in the final year of school.","meaning":"to do or have two things together","wrongMeanings":["to choose one thing and avoid another","to stop one thing before starting another","to compare one thing with another"]},{"contextId":"u7_05_combine_paraphrase","text":"In her answer, Priya decided to combine examples from school with examples from her volunteering.","meaning":"to join different things into one answer","wrongMeanings":["to separate different things into two answers","to copy different things from other people","to forget different things about her work"]}],"situationDistractors":["A student joined her love of art and her interest in computers by studying digital design.","A chef mixed spicy and sweet flavours together in the same sauce.","A girl took a part-time job in a bookshop while she studied for her exams.","The coach shouted at the players as the rain became heavier.","A lorry delivered boxes of fruit to the market early in the morning.","The student tidied her desk and closed all the windows."],"gapDistractors":[{"contextId":"u7_05_combine_gap_1","answer":"combine","wrong":["separate","cancel","refuse"]},{"contextId":"u7_05_combine_gap_2","answer":"combine","wrong":["forbid","announce","delay"]},{"contextId":"u7_05_combine_gap_3","answer":"combine","wrong":["avoid","erase","interrupt"]}],"spellingErrors":["combin","combyne","comnbine","kombine","combene","cobmine"],"wordFamilyForms":[{"form":"combine","partOfSpeech":"verb","example":"Many students combine a part-time job with their studies.","pedagogicallyUseful":true},{"form":"combination","partOfSpeech":"noun","example":"A combination of good grades and practical experience impressed the panel.","pedagogicallyUseful":true,"altExample":"The ideal candidate has a combination of technical skill and friendly manner."},{"form":"combined","partOfSpeech":"adjective","example":"The combined efforts of the whole team won the contract.","pedagogicallyUseful":true,"altExample":"Their combined income was enough to rent a small flat in the city centre."}],"masteryPassages":[{"passageId":"u7_05_combine_passage_1","contextId":"u7_05_combine_gap_1","text":"Jamal loves both music and maths, and he did not want to give up either. In the end he found a course that lets him ____ them, studying sound engineering at university.","answer":"combine"},{"passageId":"u7_05_combine_passage_2","contextId":"u7_05_combine_gap_2","text":"Employers look for people who have technical knowledge and also work well with others. Candidates who ____ both qualities have a much better chance of being offered the job.","answer":"combine"}],"contextDependentParaphrases":[],"wrongParaphrases":["to separate by size","to compare by price","to sort by colour"],"misleadingDistractors":["to separate two or more things from each other","to compare two or more things carefully","to choose one thing instead of another"],"teacherNote":"Verb: to join two or more things, skills or qualities together (combine A with B). It is usually followed by with. Boundary: combine means to join things into one; compare means to look at them side by side. The chemistry sense (substances combine) is not taught here."}]'::jsonb,'["combination","combined"]'::jsonb,'["combine skills","combine work and study","combine A with B"]'::jsonb,'live'),
('vocab_voluntary','voluntary','adjective','done, given or taken by choice, not because you are forced to','[{"senseId":"voluntary_1","meaning":"done, given or taken by choice, not because you are forced to","acceptedParaphrases":["done by free choice","not forced or required"],"masteryContexts":[{"contextId":"u7_06_voluntary_meaning","text":"Joining the school orchestra is voluntary, so nobody has to take part.","meaning":"done by choice and not required","wrongMeanings":["done in a very serious and formal way","done in secret without telling anyone","done only by the best musicians"]},{"contextId":"u7_06_voluntary_paraphrase","text":"After leaving school, Tom did voluntary work at a hospital to gain experience.","meaning":"done by choice without being paid or forced","wrongMeanings":["done as a paid job with a fixed salary","done as a punishment for breaking a rule","done as a test of physical strength"]}],"situationDistractors":["A boy gave up his Saturday morning to help clean the beach, although no one asked him to.","A girl chose to join the debating club, although it was not part of her timetable.","A woman worked at the food bank in the evenings without being paid.","The bus was late because of the heavy traffic on the main road.","A student carried a large poster into the hall and fixed it to the wall.","The teacher handed back the marked essays at the end of the lesson."],"gapDistractors":[{"contextId":"u7_06_voluntary_gap_1","answer":"voluntary","wrong":["expensive","dangerous","hungry"]},{"contextId":"u7_06_voluntary_gap_2","answer":"voluntary","wrong":["crowded","frozen","rectangular"]},{"contextId":"u7_06_voluntary_gap_3","answer":"voluntary","wrong":["wooden","furious","enormous"]}],"spellingErrors":["volluntary","volentary","voluntery","voluntry","volantary","voluntaree"],"wordFamilyForms":[{"form":"voluntary","partOfSpeech":"adjective","example":"Many charities rely on voluntary help from local people.","pedagogicallyUseful":true},{"form":"voluntarily","partOfSpeech":"adverb","example":"He left the room voluntarily, so nobody had to ask him twice.","pedagogicallyUseful":true,"altExample":"Nobody told the students to stay late, but they helped voluntarily with the final cleaning."},{"form":"volunteer","partOfSpeech":"noun","example":"A volunteer at the hospital reads to patients every Tuesday.","pedagogicallyUseful":true,"altExample":"The charity is always looking for a new volunteer to help in the shop."}],"masteryPassages":[{"passageId":"u7_06_voluntary_passage_1","contextId":"u7_06_voluntary_gap_1","text":"The school did not make students join the clean-up day. Because it was ____, only the students who really cared about the park gave up their Saturday morning.","answer":"voluntary"},{"passageId":"u7_06_voluntary_passage_2","contextId":"u7_06_voluntary_gap_2","text":"Employers often notice when a CV includes ____ activities, such as helping at a charity shop. These show that the person is willing to give time without being asked or paid.","answer":"voluntary"}],"contextDependentParaphrases":[],"wrongParaphrases":["done only in secret","done for high pay","done in a formal style"],"misleadingDistractors":["done only because a teacher insists on it","done for a large amount of money","done quickly without any planning"],"teacherNote":"Adjective: done, given or taken by choice, not because it is compulsory (voluntary work, a voluntary group). Boundary: voluntary describes choice, and says nothing about payment, although voluntary work is usually unpaid. The related noun volunteer is taught in the Word Family pathway."}]'::jsonb,'["voluntarily","volunteer"]'::jsonb,'["voluntary work","a voluntary organisation","on a voluntary basis"]'::jsonb,'live'),
('vocab_frequent','frequent','adjective','happening or done often, many times','[{"senseId":"frequent_1","meaning":"happening or done often, many times","acceptedParaphrases":["happening often","taking place many times"],"masteryContexts":[{"contextId":"u7_07_frequent_meaning","text":"The frequent changes to the timetable made it difficult for students to plan their revision.","meaning":"happening often","wrongMeanings":["happening rarely","happening suddenly","happening secretly"]},{"contextId":"u7_07_frequent_paraphrase","text":"The company is looking for someone who can make frequent visits to clients in other cities.","meaning":"happening many times","wrongMeanings":["happening one time only","happening without a reason","happening at the end of a month"]}],"situationDistractors":["The train to the city centre leaves every ten minutes all day.","A boy telephoned his grandmother two or three times a week.","The school sent a reminder email almost every day before the exam.","A single storm caused the flood in the village last winter.","The class visited the science museum once, at the end of the year.","Grandfather planted an apple tree in the garden and left it to grow."],"gapDistractors":[{"contextId":"u7_07_frequent_gap_1","answer":"frequent","wrong":["careful","silent","distant"]},{"contextId":"u7_07_frequent_gap_2","answer":"frequent","wrong":["sudden","unusual","invisible"]},{"contextId":"u7_07_frequent_gap_3","answer":"frequent","wrong":["historic","tasty","narrow"]}],"spellingErrors":["frequant","freequent","frequnt","frecuent","fequent","frekwent"],"wordFamilyForms":[{"form":"frequent","partOfSpeech":"adjective","example":"Taking frequent breaks makes it easier to concentrate on a long task.","pedagogicallyUseful":true},{"form":"frequently","partOfSpeech":"adverb","example":"Interviewers frequently ask candidates to describe a time when they solved a problem.","pedagogicallyUseful":true,"altExample":"Students who read frequently build a wider vocabulary without noticing."},{"form":"frequency","partOfSpeech":"noun","example":"The frequency of trains increases during the morning rush hour.","pedagogicallyUseful":true,"altExample":"The frequency of the bus service was reduced in the evening."}],"masteryPassages":[{"passageId":"u7_07_frequent_passage_1","contextId":"u7_07_frequent_gap_1","text":"Ravi went to every interview with a long list of notes, and he checked them again and again. His ____ practice helped him to remember the answers, but the panel wanted him to speak naturally.","answer":"frequent"},{"passageId":"u7_07_frequent_passage_2","contextId":"u7_07_frequent_gap_2","text":"The manager complained about the ____ delays on the early train. Almost every morning that month, passengers had waited for more than twenty minutes.","answer":"frequent"}],"contextDependentParaphrases":[],"wrongParaphrases":["happening only once","happening quietly","happening in secret"],"misleadingDistractors":["happening only once in a long time","happening for the first time","happening at the same moment as another event"],"teacherNote":"Adjective: happening or done often (frequent visits, frequent changes). Boundary: frequent describes how often something happens; regular describes something that happens at fixed intervals, so a frequent visitor may not come at a fixed time. The verb to frequent a place is not taught here."}]'::jsonb,'["frequently","frequency"]'::jsonb,'["frequent visits","a frequent mistake","frequent changes"]'::jsonb,'live'),
('vocab_overview','overview','noun','a short general description that shows the main features of something','[{"senseId":"overview_1","meaning":"a short general description that shows the main features of something","acceptedParaphrases":["general description of the main points","brief look at the whole subject"],"masteryContexts":[{"contextId":"u7_08_overview_meaning","text":"The first lesson gave students an overview of the whole course before the detailed units began.","meaning":"a general picture of the main features","wrongMeanings":["a detailed test of every unit","a list of grades from past students","a warning about difficult topics"]},{"contextId":"u7_08_overview_paraphrase","text":"Before going into the details of each department, the director gave an overview of the company’s history.","meaning":"a short general description of the whole","wrongMeanings":["a long explanation of one small problem","a private opinion about the staff","a final decision about the budget"]}],"situationDistractors":["A guide stood on a hill and pointed out the main parts of the city before the walking tour.","A teacher drew a simple map of the whole unit on the board in the first lesson.","The leaflet gave a quick general picture of the three main departments.","Heavy rain fell on the roof of the bus shelter all afternoon.","A boy tied his shoelaces and then ran to catch the school bus.","The librarian stamped each book and put it on the trolley."],"gapDistractors":[{"contextId":"u7_08_overview_gap_1","answer":"overview","wrong":["recipe","invitation","sandwich"]},{"contextId":"u7_08_overview_gap_2","answer":"overview","wrong":["umbrella","souvenir","bicycle"]},{"contextId":"u7_08_overview_gap_3","answer":"overview","wrong":["carpet","staircase","neighbour"]}],"spellingErrors":["overveiw","overvew","overvieuw","ovreview","overveiu","overvue"],"masteryPassages":[{"passageId":"u7_08_overview_passage_1","contextId":"u7_08_overview_gap_1","text":"The new staff were nervous about starting work in such a large company. The manager helped by giving an ____ of how the departments fit together before explaining any of the details.","answer":"overview"},{"passageId":"u7_08_overview_passage_2","contextId":"u7_08_overview_gap_2","text":"Instead of reading every page of the guide, Nadia looked at the contents list and the introduction. This gave her a quick ____ of what the book covered.","answer":"overview"}],"contextDependentParaphrases":[],"wrongParaphrases":["detailed study of one part","hidden fault in a system","final opinion at the end"],"misleadingDistractors":["a very detailed study of one small part","a hidden fault in a plan or system","a final opinion given at the end of a talk"],"teacherNote":"Noun: a short general description that shows the main features of something (an overview of the course). Boundary: an overview is a first general look at the whole subject, while a summary shortens something already given; an overview does not go into detail. It is one word (not over view)."}]'::jsonb,'[]'::jsonb,'["a brief overview","give an overview","an overview of the course"]'::jsonb,'live'),
('vocab_candidate','candidate','noun','a person who is being considered for a job, or who is taking an exam','[{"senseId":"candidate_1","meaning":"a person who is being considered for a job, or who is taking an exam","acceptedParaphrases":["person being considered for a job","person taking an exam"],"masteryContexts":[{"contextId":"u7_09_candidate_meaning","text":"The company offered the job to the strongest candidate after a second round of questions.","meaning":"a person being considered for a job","wrongMeanings":["a person who has already left the company","a person who prepares the written questions","a person who has chosen not to work"]},{"contextId":"u7_09_candidate_paraphrase","text":"Every candidate must arrive at the exam hall at least fifteen minutes before the start.","meaning":"a person who is taking an exam","wrongMeanings":["a person who writes the exam questions","a person who teaches the exam course","a person who marks the exam papers"]}],"situationDistractors":["A woman waited outside the room because she was one of three people shortlisted for the post.","A student sat at a desk with a number card, waiting for the invigilator to start the paper.","A man was called in for a second interview after the first round.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_09_candidate_gap_1","answer":"candidate","wrong":["passenger","engine","meadow"]},{"contextId":"u7_09_candidate_gap_2","answer":"candidate","wrong":["harbour","recipe","ticket"]},{"contextId":"u7_09_candidate_gap_3","answer":"candidate","wrong":["museum","umbrella","souvenir"]}],"spellingErrors":["canidate","candidat","candadate","candiate","candidte","kandidate"],"masteryPassages":[{"passageId":"u7_09_candidate_passage_1","contextId":"u7_09_candidate_gap_1","text":"The panel interviewed five people for the post of science technician. By the end of the day they all agreed that the second ____ had the best answers and the most relevant experience.","answer":"candidate"},{"passageId":"u7_09_candidate_passage_2","contextId":"u7_09_candidate_gap_2","text":"Before the exam began, the invigilator checked the name on every desk. Each ____ was reminded to switch off their phone and to read the instructions carefully.","answer":"candidate"}],"contextDependentParaphrases":[],"wrongParaphrases":["person who left a long job","person who writes the questions","person who advertises the job"],"misleadingDistractors":["a person who has left a job after many years","a person who prepares the questions for an exam","a person who advertises a job for a company"],"teacherNote":"Noun: a person who is being considered for a job, or who is sitting an exam. Boundary: a candidate is already in the process (shortlisted, or entered for the exam); an applicant is a person who has only just asked. British exam use: the candidate number on a question paper."}]'::jsonb,'[]'::jsonb,'["a strong candidate","an ideal candidate","a candidate for the job"]'::jsonb,'live'),
('vocab_interviewer','interviewer','noun','a person who asks questions in an interview to find out about someone','[{"senseId":"interviewer_1","meaning":"a person who asks questions in an interview to find out about someone","acceptedParaphrases":["person who asks the questions","person who questions a candidate"],"masteryContexts":[{"contextId":"u7_10_interviewer_meaning","text":"The interviewer asked Ben to describe a time when he had worked as part of a team.","meaning":"the person who asks the questions at a job meeting","wrongMeanings":["the person who answers the questions at a job meeting","the person who writes the answers after a job meeting","the person who applies for a job at a job meeting"]},{"contextId":"u7_10_interviewer_paraphrase","text":"A friendly interviewer can help nervous candidates to relax and speak more clearly.","meaning":"a person who asks questions to find out about someone","wrongMeanings":["a person who gives advice after an exam","a person who teaches new employees","a person who writes reports about candidates"]}],"situationDistractors":["A woman at a desk asked a young man about his experience and made notes while he spoke.","A reporter asked the footballer three questions after the match for a radio programme.","A teacher asked a student why she had chosen to apply for the course.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_10_interviewer_gap_1","answer":"interviewer","wrong":["passenger","harbour","recipe"]},{"contextId":"u7_10_interviewer_gap_2","answer":"interviewer","wrong":["ticket","museum","umbrella"]},{"contextId":"u7_10_interviewer_gap_3","answer":"interviewer","wrong":["carpet","souvenir","bicycle"]}],"spellingErrors":["intervewer","interveiwer","interviwer","enterviewer","interviewr","interviewar"],"masteryPassages":[{"passageId":"u7_10_interviewer_passage_1","contextId":"u7_10_interviewer_gap_1","text":"Aisha was nervous when she walked into the room, but the ____ smiled and asked her an easy first question. This helped her to relax and give clear answers for the rest of the meeting.","answer":"interviewer"},{"passageId":"u7_10_interviewer_passage_2","contextId":"u7_10_interviewer_gap_2","text":"A good ____ does not only listen to what a candidate says. She also watches how the person sits and speaks, because body language can show confidence or worry.","answer":"interviewer"}],"contextDependentParaphrases":[],"wrongParaphrases":["person who answers questions","person who writes job adverts","person who checks answers later"],"misleadingDistractors":["a person who answers the questions","a person who writes the job advertisement","a person who checks the answers afterwards"],"teacherNote":"Noun: a person who asks questions in an interview, for example for a job, a place at college, or a television programme. Boundary: the interviewer asks; the interviewee answers (a separate target in this unit). Stress: in-ter-view-er."}]'::jsonb,'[]'::jsonb,'["a friendly interviewer","the interviewer asked","impress the interviewer"]'::jsonb,'live')
