('u7_01_applicant_meaning','vocab_applicant','u7_01_applicant','applicant_1','meaning_context','The manager told the last applicant to wait outside until the panel was ready.',null,'["person who asks formally for a job"]'::jsonb,null,'live'),
('u7_01_applicant_paraphrase','vocab_applicant','u7_01_applicant','applicant_1','paraphrase_context','The manager told the last person who asked formally for the job to wait outside until the panel was ready.','person who asked formally for the job','["applicant"]'::jsonb,null,'live'),
('u7_01_applicant_production','vocab_applicant','u7_01_applicant','applicant_1','production_context','A fair college treats someone who makes a formal request for a place with the same respect, whatever their background.','someone who makes a formal request for a place','["applicant"]'::jsonb,null,'live'),
('u7_01_applicant_gap_1','vocab_applicant','u7_01_applicant','applicant_1','gap_fill','A successful applicant will receive a letter within two weeks of the interview.','applicant','["applicant"]'::jsonb,null,'live'),
('u7_01_applicant_gap_2','vocab_applicant','u7_01_applicant','applicant_1','gap_fill','The company asked every applicant to explain in writing why they wanted the job.','applicant','["applicant"]'::jsonb,null,'live'),
('u7_01_applicant_gap_3','vocab_applicant','u7_01_applicant','applicant_1','gap_fill','Only one applicant had experience of working with young children, so the school invited her first.','applicant','["applicant"]'::jsonb,null,'live'),
('u7_02_qualifications_meaning','vocab_qualifications','u7_02_qualifications','qualifications_1','meaning_context','Her qualifications include a degree in biology and a diploma in teaching.',null,'["exam results and training you have completed"]'::jsonb,null,'live'),
('u7_02_qualifications_paraphrase','vocab_qualifications','u7_02_qualifications','qualifications_1','paraphrase_context','Her exam results and training she has completed include a degree in biology and a diploma in teaching.','exam results and training she has completed','["qualifications"]'::jsonb,null,'live'),
('u7_02_qualifications_production','vocab_qualifications','u7_02_qualifications','qualifications_1','production_context','Most employers ask for official proof of what you have studied, as well as a short letter about your interests.','official proof of what you have studied','["qualifications"]'::jsonb,null,'live'),
('u7_02_qualifications_gap_1','vocab_qualifications','u7_02_qualifications','qualifications_1','gap_fill','Her qualifications are excellent, but the company wants someone with more experience of teamwork.','qualifications','["qualifications"]'::jsonb,null,'live'),
