('u7_02_qualifications_gap_3','vocab_qualifications','u7_02_qualifications','qualifications_1','gap_fill','Nurses in this hospital need formal qualifications as well as a kind and patient personality.','qualifications','["qualifications"]'::jsonb,null,'live'),
('u7_03_demonstrate_meaning','vocab_demonstrate','u7_03_demonstrate','demonstrate_1','meaning_context','In the interview, candidates were asked to demonstrate how they would deal with an angry customer.',null,'["show clearly that you can"]'::jsonb,null,'live'),
