('u7_03_demonstrate_production','vocab_demonstrate','u7_03_demonstrate','demonstrate_1','production_context','Good applicants try to prove by showing in practice that they can work well in a team.','prove by showing in practice','["demonstrate"]'::jsonb,null,'live'),
('u7_03_demonstrate_gap_1','vocab_demonstrate','u7_03_demonstrate','demonstrate_1','gap_fill','Use specific examples from your life to demonstrate that you can solve problems under pressure.','demonstrate','["demonstrate"]'::jsonb,null,'live'),
('u7_03_demonstrate_gap_2','vocab_demonstrate','u7_03_demonstrate','demonstrate_1','gap_fill','The test is designed to demonstrate whether a candidate can think clearly in difficult situations.','demonstrate','["demonstrate"]'::jsonb,null,'live'),
('u7_03_demonstrate_gap_3','vocab_demonstrate','u7_03_demonstrate','demonstrate_1','gap_fill','She wanted to demonstrate her speaking skills, so she gave a short, confident talk about her experience.','demonstrate','["demonstrate"]'::jsonb,null,'live'),
('u7_04_summary_meaning','vocab_summary','u7_04_summary','summary_1','meaning_context','At the end of the meeting, the chairperson gave a brief summary of what had been agreed.',null,'["short account of the main points"]'::jsonb,null,'live'),
('u7_04_summary_paraphrase','vocab_summary','u7_04_summary','summary_1','paraphrase_context','At the end of the meeting, the chairperson gave a brief short account of the main points of what had been agreed.','short account of the main points','["summary"]'::jsonb,null,'live'),
