('u7_04_summary_gap_3','vocab_summary','u7_04_summary','summary_1','gap_fill','The report ended with a short summary of the findings and three clear recommendations.','summary','["summary"]'::jsonb,null,'live'),
('u7_05_combine_meaning','vocab_combine','u7_05_combine','combine_1','meaning_context','The best candidates combine good communication skills with a calm and polite manner.',null,'["join together"]'::jsonb,null,'live'),
('u7_05_combine_paraphrase','vocab_combine','u7_05_combine','combine_1','paraphrase_context','The best candidates join together good communication skills with a calm and polite manner.','join together','["combine"]'::jsonb,null,'live'),
('u7_05_combine_production','vocab_combine','u7_05_combine','combine_1','production_context','Many students like to put two or more things together, such as a part-time job and weekend sport.','put two or more things together','["combine"]'::jsonb,null,'live'),
('u7_05_combine_gap_1','vocab_combine','u7_05_combine','combine_1','gap_fill','The course allows students to combine languages with business, which helps them find international work.','combine','["combine"]'::jsonb,null,'live'),
('u7_05_combine_gap_2','vocab_combine','u7_05_combine','combine_1','gap_fill','It is hard to combine a full-time job with studying for exams in the evening.','combine','["combine"]'::jsonb,null,'live'),
('u7_05_combine_gap_3','vocab_combine','u7_05_combine','combine_1','gap_fill','A good answer should combine a clear opinion with a specific example.','combine','["combine"]'::jsonb,null,'live'),
('u7_06_voluntary_meaning','vocab_voluntary','u7_06_voluntary','voluntary_1','meaning_context','Attendance at the careers workshop is voluntary, but most students decide to go.',null,'["done by free choice"]'::jsonb,null,'live'),
