('u7_06_voluntary_gap_3','vocab_voluntary','u7_06_voluntary','voluntary_1','gap_fill','The interview panel was impressed by his voluntary work at the local youth centre.','voluntary','["voluntary"]'::jsonb,null,'live'),
('u7_07_frequent_meaning','vocab_frequent','u7_07_frequent','frequent_1','meaning_context','Frequent practice before an interview helps you to answer questions calmly.',null,'["happening often"]'::jsonb,null,'live'),
