('u7_idea_applicant',7,'idea_set','{"originalIdea":"Every applicant must send a letter and a CV before the closing date.","accurateParaphrases":["Everybody who asks formally for the job has to submit a letter and a CV by the final day for entries.","Each person who wants the post must send a covering letter and a CV before the entries close.","A letter and a CV have to be sent in by every person asking for the position before the deadline."],"meaningInvariants":[{"type":"quantity","value":"every"}],"distractors":[{"text":"Some applicants must send a letter and a CV before the closing date.","misconceptionCategory":"quantity_change"},{"text":"Every applicant may send a letter and a CV after the closing date.","misconceptionCategory":"time_change"},{"text":"Every interviewer must send a letter and a CV before the closing date.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_applicant"],"primaryEvidenceTargetId":"vocab_applicant"}'::jsonb,'live'),
('u7_idea_qualifications',7,'idea_set','{"originalIdea":"Employers often ask for qualifications as well as practical experience.","accurateParaphrases":["Companies frequently want exam results and training in addition to practical experience.","Employers usually expect proof of study as well as skills gained from doing the job.","Many firms look for official certificates and also for practical experience."],"meaningInvariants":[{"type":"quantity","value":"often"}],"distractors":[{"text":"Employers never ask for qualifications as well as practical experience.","misconceptionCategory":"polarity_change"},{"text":"Employers ask for practical experience instead of any qualifications.","misconceptionCategory":"omitted_information"},{"text":"Employers often ask for hobbies as well as practical experience.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_qualifications"],"primaryEvidenceTargetId":"vocab_qualifications"}'::jsonb,'live'),
('u7_idea_demonstrate',7,'idea_set','{"originalIdea":"Candidates should demonstrate their skills by giving clear examples.","accurateParaphrases":["Applicants ought to show what they can do by describing definite examples.","People attending an interview should prove their abilities with specific examples.","Giving clear examples is how candidates ought to show their skills."],"meaningInvariants":[{"type":"cause_effect","value":"by giving clear examples"}],"distractors":[{"text":"Candidates should hide their skills by giving clear examples.","misconceptionCategory":"polarity_change"},{"text":"Candidates should demonstrate their skills without giving any examples.","misconceptionCategory":"omitted_information"},{"text":"Candidates should compare their skills by giving clear examples.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_demonstrate"],"primaryEvidenceTargetId":"vocab_demonstrate"}'::jsonb,'live'),
('u7_idea_summary',7,'idea_set','{"originalIdea":"The final page of the report gives a summary of the main findings.","accurateParaphrases":["The last page of the report briefly states the most important findings.","On the closing page of the report, the key findings are listed in short form.","A short account of the main results appears on the final page of the report."],"meaningInvariants":[{"type":"quantity","value":"main findings"}],"distractors":[{"text":"The final page of the report gives every single finding in full detail.","misconceptionCategory":"degree_change"},{"text":"The first page of the report gives a summary of the main findings.","misconceptionCategory":"meaning_confusion"},{"text":"The final page of the report gives a summary of the minor findings.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_summary"],"primaryEvidenceTargetId":"vocab_summary"}'::jsonb,'live'),
('u7_idea_combine',7,'idea_set','{"originalIdea":"Many students combine part-time work with their studies.","accurateParaphrases":["Lots of students do a part-time job at the same time as studying.","It is common for students to join a part-time job and their studies together.","A good number of students manage a part-time job alongside their studies."],"meaningInvariants":[{"type":"quantity","value":"many"}],"distractors":[{"text":"Few students combine part-time work with their studies.","misconceptionCategory":"quantity_change"},{"text":"Many students replace their studies with part-time work.","misconceptionCategory":"meaning_confusion"},{"text":"Many students combine part-time work with their holidays.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_combine"],"primaryEvidenceTargetId":"vocab_combine"}'::jsonb,'live'),
('u7_idea_voluntary',7,'idea_set','{"originalIdea":"Taking part in the school trip is voluntary, but most students have signed up.","accurateParaphrases":["Nobody has to go on the school trip, yet most students have put their names down.","The trip is not compulsory, although the majority of students have registered.","Students can choose whether or not to join the school trip, and most have decided to."],"meaningInvariants":[{"type":"degree","value":"not compulsory"}],"distractors":[{"text":"Taking part in the school trip is compulsory, and most students have signed up.","misconceptionCategory":"polarity_change"},{"text":"Taking part in the school trip is voluntary, and few students have signed up.","misconceptionCategory":"quantity_change"},{"text":"Taking part in the school trip is voluntary, so no student has signed up.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_voluntary"],"primaryEvidenceTargetId":"vocab_voluntary"}'::jsonb,'live'),
('u7_idea_frequent',7,'idea_set','{"originalIdea":"There are frequent delays on the line between the village and the city.","accurateParaphrases":["The trains between the village and the city are often late.","Delays happen many times on the route linking the village with the city.","Passengers travelling between the village and the city regularly face late services."],"meaningInvariants":[{"type":"quantity","value":"often"}],"distractors":[{"text":"There are rare delays on the line between the village and the city.","misconceptionCategory":"quantity_change"},{"text":"There are frequent delays on the line between the city and the airport.","misconceptionCategory":"meaning_confusion"},{"text":"There are frequent improvements on the line between the village and the city.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_frequent"],"primaryEvidenceTargetId":"vocab_frequent"}'::jsonb,'live'),
('u7_idea_overview',7,'idea_set','{"originalIdea":"The introduction gives a general overview of the topic without going into detail.","accurateParaphrases":["The opening section briefly describes the main features of the subject and leaves out the fine detail.","In the first part of the text, the topic is introduced broadly, with no close detail.","The beginning of the piece offers a wide, general picture of the subject and does not explore small points."],"meaningInvariants":[{"type":"degree","value":"without going into detail"}],"distractors":[{"text":"The introduction gives a detailed analysis of the topic and explains every small point.","misconceptionCategory":"degree_change"},{"text":"The conclusion gives a general overview of the topic without going into detail.","misconceptionCategory":"meaning_confusion"},{"text":"The introduction gives a general overview of the topic and then goes into great detail.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_overview"],"primaryEvidenceTargetId":"vocab_overview"}'::jsonb,'live'),
('u7_idea_candidate',7,'idea_set','{"originalIdea":"The strongest candidate had experience of working abroad and spoke three languages.","accurateParaphrases":["The best person being considered had worked overseas and could speak three languages.","Having lived and worked abroad and speaking three languages made one person the most promising choice.","The most impressive person on the list had overseas work history and three languages."],"meaningInvariants":[{"type":"degree","value":"strongest"}],"distractors":[{"text":"The weakest candidate had experience of working abroad and spoke three languages.","misconceptionCategory":"polarity_change"},{"text":"The strongest candidate had experience of working abroad but spoke only one language.","misconceptionCategory":"quantity_change"},{"text":"The strongest interviewer had experience of working abroad and spoke three languages.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_candidate"],"primaryEvidenceTargetId":"vocab_candidate"}'::jsonb,'live'),
('u7_idea_interviewer',7,'idea_set','{"originalIdea":"The interviewer asked each candidate the same five questions.","accurateParaphrases":["Every person being considered was given the same five questions by the person running the meeting.","The person in charge of the meeting put identical questions to all the candidates.","All of the candidates were asked five identical questions by the one who led the session."],"meaningInvariants":[{"type":"quantity","value":"same five questions"}],"distractors":[{"text":"The interviewer asked each candidate a different set of questions.","misconceptionCategory":"comparison_change"},{"text":"The interviewer asked only one candidate the same five questions.","misconceptionCategory":"quantity_change"},{"text":"The candidates asked the interviewer the same five questions.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_interviewer"],"primaryEvidenceTargetId":"vocab_interviewer"}'::jsonb,'live'),
('u7_idea_interviewee',7,'idea_set','{"originalIdea":"The interviewee answered every question clearly and politely.","accurateParaphrases":["The person being questioned replied to each question in a clear and courteous way.","Each question was answered by the person at the meeting in a polite and clear manner.","Every one of the questions received a clear, polite reply from the person being asked."],"meaningInvariants":[{"type":"quantity","value":"every question"}],"distractors":[{"text":"The interviewee answered some questions clearly and politely.","misconceptionCategory":"quantity_change"},{"text":"The interviewer answered every question clearly and politely.","misconceptionCategory":"meaning_confusion"},{"text":"The interviewee answered every question clearly but rudely.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_interviewee"],"primaryEvidenceTargetId":"vocab_interviewee"}'::jsonb,'live'),
('u7_idea_referee',7,'idea_set','{"originalIdea":"Most employers will contact a referee before they offer a job.","accurateParaphrases":["The majority of employers get in touch with a person named on the form before making an offer.","Before offering the post, most companies phone or email someone who can speak about the applicant.","It is normal for employers to talk to a person who knows the applicant well before they give the job."],"meaningInvariants":[{"type":"time","value":"before they offer a job"}],"distractors":[{"text":"Most employers will contact a referee after they offer a job.","misconceptionCategory":"time_change"},{"text":"Few employers will contact a referee before they offer a job.","misconceptionCategory":"quantity_change"},{"text":"Most employers will contact a candidate before they offer a job.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_referee"],"primaryEvidenceTargetId":"vocab_referee"}'::jsonb,'live'),
('u7_idea_reference',7,'idea_set','{"originalIdea":"The employer asked for a reference from her last manager before making an offer.","accurateParaphrases":["Before offering her the post, the company wanted a statement about her from her previous boss.","Her last manager was asked by the employer to write a recommendation before the offer was made.","The company required a written opinion of her from the person who had managed her most recently."],"meaningInvariants":[{"type":"time","value":"before making an offer"}],"distractors":[{"text":"The employer asked for a reference from her last manager after making an offer.","misconceptionCategory":"time_change"},{"text":"The employer asked for a reference from her last teacher before making an offer.","misconceptionCategory":"meaning_confusion"},{"text":"The employer refused a reference from her last manager before making an offer.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_reference"],"primaryEvidenceTargetId":"vocab_reference"}'::jsonb,'live'),
('u7_idea_proficiency',7,'idea_set','{"originalIdea":"Proficiency in English is essential for most jobs in the tourist industry.","accurateParaphrases":["A high level of skill in English is necessary for the majority of posts in tourism.","Most positions in the tourist industry cannot be done without being very good at English.","To work in tourism, you generally have to be highly skilled in English."],"meaningInvariants":[{"type":"degree","value":"essential"}],"distractors":[{"text":"Proficiency in English is helpful but not essential for most jobs in the tourist industry.","misconceptionCategory":"degree_change"},{"text":"Proficiency in English is essential for a few jobs in the tourist industry.","misconceptionCategory":"quantity_change"},{"text":"Proficiency in English is essential for most jobs in the banking industry.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_proficiency"],"primaryEvidenceTargetId":"vocab_proficiency"}'::jsonb,'live'),
('u7_idea_enthusiastic',7,'idea_set','{"originalIdea":"The interviewer was impressed by how enthusiastic the candidate was about the job.","accurateParaphrases":["The person running the meeting liked how keen and excited the applicant seemed about the post.","How eager the candidate appeared for the job made a strong impression on the interviewer.","The one asking the questions admired the energy and interest the candidate showed for the position."],"meaningInvariants":[{"type":"cause_effect","value":"impressed by how enthusiastic"}],"distractors":[{"text":"The interviewer was worried by how enthusiastic the candidate was about the job.","misconceptionCategory":"polarity_change"},{"text":"The interviewer was impressed by how nervous the candidate was about the job.","misconceptionCategory":"meaning_confusion"},{"text":"The interviewer was impressed by how enthusiastic the candidate was about the salary.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_enthusiastic"],"primaryEvidenceTargetId":"vocab_enthusiastic"}'::jsonb,'live'),
('u7_idea_availability',7,'idea_set','{"originalIdea":"Because of her limited availability, she can only work on Saturday mornings.","accurateParaphrases":["She is free to work only on Saturday mornings, so her time is restricted.","Her free time is very limited, so Saturday mornings are the only time she can work.","The only time she can come in is Saturday morning, because she is not free at other times."],"meaningInvariants":[{"type":"cause_effect","value":"because of her limited availability"}],"distractors":[{"text":"Because of her excellent availability, she can work on any day of the week.","misconceptionCategory":"polarity_change"},{"text":"Because of her limited availability, she can only work on Sunday afternoons.","misconceptionCategory":"meaning_confusion"},{"text":"Although she is limited in availability, she works on every day of the week.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_availability_7"],"primaryEvidenceTargetId":"vocab_availability_7"}'::jsonb,'live'),
('u7_idea_compromise',7,'idea_set','{"originalIdea":"The two managers reached a compromise after a long discussion.","accurateParaphrases":["After talking for a long time, the two managers agreed on a solution that each of them could accept.","Following lengthy talks, the two managers settled their disagreement with each giving something up.","A solution acceptable to both managers was finally found after a lengthy conversation."],"meaningInvariants":[{"type":"time","value":"after a long discussion"}],"distractors":[{"text":"The two managers reached a compromise before any discussion took place.","misconceptionCategory":"time_change"},{"text":"The two managers refused to reach a compromise after a long discussion.","misconceptionCategory":"polarity_change"},{"text":"The two managers reached a victory after a long discussion.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_compromise"],"primaryEvidenceTargetId":"vocab_compromise"}'::jsonb,'live'),
('u7_idea_dominate',7,'idea_set','{"originalIdea":"One loud candidate tended to dominate the group discussion.","accurateParaphrases":["One candidate with a loud voice often took over the group conversation.","The group conversation was frequently controlled by a single noisy applicant.","A noisy member of the group usually spoke so much that he led the whole discussion."],"meaningInvariants":[{"type":"quantity","value":"one loud candidate"}],"distractors":[{"text":"Every loud candidate tended to dominate the group discussion.","misconceptionCategory":"quantity_change"},{"text":"One loud candidate tended to avoid the group discussion.","misconceptionCategory":"polarity_change"},{"text":"One loud candidate tended to organise the group discussion.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_dominate"],"primaryEvidenceTargetId":"vocab_dominate"}'::jsonb,'live'),
('u7_idea_strategy',7,'idea_set','{"originalIdea":"The company has a clear strategy for recruiting young people.","accurateParaphrases":["The firm has a definite plan for employing young people.","There is a well-defined plan at the business for taking on young workers.","The business knows exactly how it intends to bring in younger staff."],"meaningInvariants":[{"type":"degree","value":"clear"}],"distractors":[{"text":"The company has no strategy for recruiting young people.","misconceptionCategory":"polarity_change"},{"text":"The company has a confusing strategy for recruiting young people.","misconceptionCategory":"degree_change"},{"text":"The company has a clear strategy for training young people.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_strategy_7"],"primaryEvidenceTargetId":"vocab_strategy_7"}'::jsonb,'live'),
('u7_idea_flexible',7,'idea_set','{"originalIdea":"The company offers flexible working hours to all its staff.","accurateParaphrases":["The firm lets every employee adjust their working times.","All of the business’s workers can change when they start and finish work.","Every member of staff at the company is allowed to vary their hours."],"meaningInvariants":[{"type":"quantity","value":"all its staff"}],"distractors":[{"text":"The company offers flexible working hours to some of its staff.","misconceptionCategory":"quantity_change"},{"text":"The company offers fixed working hours to all its staff.","misconceptionCategory":"polarity_change"},{"text":"The company offers flexible working holidays to all its staff.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_flexible"],"primaryEvidenceTargetId":"vocab_flexible"}'::jsonb,'live'),
('u7_idea_schedule',7,'idea_set','{"originalIdea":"The interview schedule was changed because two candidates were ill.","accurateParaphrases":["The plan of times for the interviews had to be altered as two applicants were unwell.","Because two candidates could not attend through illness, the timetable of interviews was rearranged.","The timings for the interviews were revised after two of the candidates fell ill."],"meaningInvariants":[{"type":"cause_effect","value":"because two candidates were ill"}],"distractors":[{"text":"The interview schedule was cancelled because two candidates were ill.","misconceptionCategory":"meaning_confusion"},{"text":"The interview schedule was changed although two candidates were ill.","misconceptionCategory":"cause_effect_change"},{"text":"The interview schedule was changed because two candidates were late.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_schedule"],"primaryEvidenceTargetId":"vocab_schedule"}'::jsonb,'live'),
('u7_idea_expectation',7,'idea_set','{"originalIdea":"The manager’s expectation is that all staff will arrive before nine o’clock.","accurateParaphrases":["The manager believes that every member of staff should be there before nine.","All workers are expected by the manager to arrive earlier than nine o’clock.","The manager thinks that nobody on the team will turn up after nine."],"meaningInvariants":[{"type":"quantity","value":"all staff"}],"distractors":[{"text":"The manager’s expectation is that some staff will arrive before nine o’clock.","misconceptionCategory":"quantity_change"},{"text":"The manager’s expectation is that all staff will arrive after nine o’clock.","misconceptionCategory":"time_change"},{"text":"The manager’s promise is that all staff will arrive before nine o’clock.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_expectation"],"primaryEvidenceTargetId":"vocab_expectation"}'::jsonb,'live'),
('u7_idea_impress',7,'idea_set','{"originalIdea":"Candidates can impress interviewers by researching the company carefully.","accurateParaphrases":["Applicants can win the respect of the panel by finding out a lot about the firm beforehand.","Studying the company with care makes it possible for candidates to earn admiration from the people asking the questions.","By learning plenty about the business first, people attending the meeting can make a strong positive effect."],"meaningInvariants":[{"type":"cause_effect","value":"by researching the company"}],"distractors":[{"text":"Candidates can impress interviewers by ignoring the company completely.","misconceptionCategory":"polarity_change"},{"text":"Candidates can impress interviewers by arriving late and speaking quickly.","misconceptionCategory":"meaning_confusion"},{"text":"Candidates can only impress interviewers by researching the company.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_impress"],"primaryEvidenceTargetId":"vocab_impress"}'::jsonb,'live'),
('u7_idea_respond',7,'idea_set','{"originalIdea":"The company responded to all the applications within a week.","accurateParaphrases":["The firm gave an answer to every application in seven days or less.","Within a week, every application had received a reply from the company.","All of the forms that were sent in were answered by the business in under seven days."],"meaningInvariants":[{"type":"quantity","value":"all the applications"}],"distractors":[{"text":"The company responded to some of the applications within a week.","misconceptionCategory":"quantity_change"},{"text":"The company responded to all the applications after a month.","misconceptionCategory":"time_change"},{"text":"The company rejected all the applications within a week.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_respond_7"],"primaryEvidenceTargetId":"vocab_respond_7"}'::jsonb,'live'),
('u7_idea_relevant',7,'idea_set','{"originalIdea":"The interviewer asked the candidate to give only relevant examples.","accurateParaphrases":["The person asking the questions wanted the applicant to use only examples connected to the subject.","The candidate was told by the interviewer to include nothing that did not relate to the question.","Only examples that were useful for the topic were wanted by the one conducting the meeting."],"meaningInvariants":[{"type":"quantity","value":"only"}],"distractors":[{"text":"The interviewer asked the candidate to give many examples, relevant or not.","misconceptionCategory":"omitted_information"},{"text":"The candidate asked the interviewer to give only relevant examples.","misconceptionCategory":"meaning_confusion"},{"text":"The interviewer asked the candidate to give only recent examples.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_relevant_7"],"primaryEvidenceTargetId":"vocab_relevant_7"}'::jsonb,'live'),
('u7_idea_contribute',7,'idea_set','{"originalIdea":"Every candidate was asked to contribute at least one idea to the group task.","accurateParaphrases":["All of the candidates had to offer a minimum of one idea during the group exercise.","Each person at the assessment was required to add at least a single suggestion to the team activity.","The group task required one or more ideas from every single candidate."],"meaningInvariants":[{"type":"quantity","value":"at least one"}],"distractors":[{"text":"Every candidate was asked to contribute no more than one idea to the group task.","misconceptionCategory":"quantity_change"},{"text":"Some candidates were asked to contribute at least one idea to the group task.","misconceptionCategory":"quantity_change"},{"text":"Every candidate was asked to contribute at least one question to the group task.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_contribute"],"primaryEvidenceTargetId":"vocab_contribute"}'::jsonb,'live'),
('u7_idea_coherent',7,'idea_set','{"originalIdea":"The candidate gave a coherent answer to every question.","accurateParaphrases":["The applicant replied to each question in a clear and logical way.","Every question received an answer from the candidate that was well organised and easy to follow.","For all of the questions, the candidate’s replies had ideas that fitted together sensibly."],"meaningInvariants":[{"type":"quantity","value":"every question"}],"distractors":[{"text":"The candidate gave a coherent answer to only one question.","misconceptionCategory":"quantity_change"},{"text":"The candidate gave a confusing answer to every question.","misconceptionCategory":"polarity_change"},{"text":"The candidate gave a coherent answer to none of the questions.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_coherent"],"primaryEvidenceTargetId":"vocab_coherent"}'::jsonb,'live'),
('u7_idea_implication',7,'idea_set','{"originalIdea":"The implication of her silence was that she disagreed with the decision.","accurateParaphrases":["Her silence suggested, without saying so, that she did not agree with the decision.","Although she said nothing, it seemed from her silence that she was against the decision.","By staying quiet, she showed indirectly that she disagreed with what had been decided."],"meaningInvariants":[{"type":"degree","value":"suggested, not stated"}],"distractors":[{"text":"She said clearly that she disagreed with the decision.","misconceptionCategory":"degree_change"},{"text":"The implication of her silence was that she agreed with the decision.","misconceptionCategory":"polarity_change"},{"text":"The implication of her speech was that she disagreed with the decision.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_implication"],"primaryEvidenceTargetId":"vocab_implication"}'::jsonb,'live'),
('u7_idea_register',7,'idea_set','{"originalIdea":"Candidates should use a formal register in an interview but a friendly one when chatting to the receptionist.","accurateParaphrases":["In the interview itself, applicants ought to speak in a formal style, though a more relaxed style suits a chat with the receptionist.","A formal level of language is right for the meeting, while friendly language is fine with the person at the front desk.","People attending the interview should be formal in the room and more relaxed when talking to the receptionist."],"meaningInvariants":[{"type":"comparison","value":"formal versus friendly"}],"distractors":[{"text":"Candidates should use a friendly register in an interview but a formal one when chatting to the receptionist.","misconceptionCategory":"polarity_change"},{"text":"Candidates should use a formal register everywhere, even with the receptionist.","misconceptionCategory":"omitted_information"},{"text":"Candidates should use a loud voice in an interview but a quiet one when chatting to the receptionist.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_register"],"primaryEvidenceTargetId":"vocab_register"}'::jsonb,'live'),
('u7_idea_format',7,'idea_set','{"originalIdea":"The format of the interview was a short talk followed by questions.","accurateParaphrases":["The interview was arranged as a brief talk and then some questions.","A short presentation came first in the interview, and questions came afterwards.","The pattern of the interview was a brief talk, with questions after it."],"meaningInvariants":[{"type":"time","value":"followed by"}],"distractors":[{"text":"The format of the interview was questions followed by a short talk.","misconceptionCategory":"time_change"},{"text":"The format of the interview was a short talk without any questions.","misconceptionCategory":"omitted_information"},{"text":"The length of the interview was a short talk followed by questions.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_format"],"primaryEvidenceTargetId":"vocab_format"}'::jsonb,'live'),
('u7_idea_membership',7,'idea_set','{"originalIdea":"Annual membership of the club costs less for students than for adults.","accurateParaphrases":["It is cheaper for students than for adults to belong to the club for a year.","Students pay a lower price than adults for a year of belonging to the club.","The yearly fee for being part of the club is smaller for students than adults."],"meaningInvariants":[{"type":"comparison","value":"less for students than for adults"}],"distractors":[{"text":"Annual membership of the club costs more for students than for adults.","misconceptionCategory":"comparison_change"},{"text":"Monthly membership of the club costs less for students than for adults.","misconceptionCategory":"time_change"},{"text":"Annual membership of the club costs the same for students and for adults.","misconceptionCategory":"comparison_change"}],"linkedVocabularyIds":["vocab_membership"],"primaryEvidenceTargetId":"vocab_membership"}'::jsonb,'live'),
('u7_idea_certificate',7,'idea_set','{"originalIdea":"Every student who passes the final test will receive a certificate.","accurateParaphrases":["All the students who succeed in the last test will be given an official document.","An official paper will be handed to each student who gets through the final exam.","Anyone who passes the concluding test will get official proof that they succeeded."],"meaningInvariants":[{"type":"quantity","value":"every student who passes"}],"distractors":[{"text":"Some students who pass the final test will receive a certificate.","misconceptionCategory":"quantity_change"},{"text":"Every student who takes the final test will receive a certificate.","misconceptionCategory":"omitted_information"},{"text":"Every student who passes the final test will receive a prize.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_certificate"],"primaryEvidenceTargetId":"vocab_certificate"}'::jsonb,'live'),
('u7_idea_qualification',7,'idea_set','{"originalIdea":"Good communication is the most important qualification for the post of receptionist.","accurateParaphrases":["Being able to communicate well matters more than anything else for the receptionist’s job.","The skill that counts most for working as a receptionist is communicating well.","For the receptionist position, the quality needed above all others is good communication."],"meaningInvariants":[{"type":"degree","value":"most important"}],"distractors":[{"text":"Good communication is the least important qualification for the post of receptionist.","misconceptionCategory":"polarity_change"},{"text":"Good communication is one useful qualification for the post of receptionist.","misconceptionCategory":"degree_change"},{"text":"Good communication is the most important qualification for the post of manager.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_qualification_7"],"primaryEvidenceTargetId":"vocab_qualification_7"}'::jsonb,'live'),
('u7_idea_experience',7,'idea_set','{"originalIdea":"Employers often prefer candidates with practical experience to those with only qualifications.","accurateParaphrases":["Companies frequently choose people who have done the work in practice rather than those who only have exam results.","Applicants who have learned by doing tend to be favoured by firms over those who have only studied.","It is common for businesses to favour hands-on skill over a list of certificates."],"meaningInvariants":[{"type":"comparison","value":"prefer experience to qualifications"}],"distractors":[{"text":"Employers often prefer candidates with only qualifications to those with practical experience.","misconceptionCategory":"comparison_change"},{"text":"Employers never prefer candidates with practical experience to those with only qualifications.","misconceptionCategory":"quantity_change"},{"text":"Employers often prefer candidates with practical hobbies to those with only qualifications.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_experience"],"primaryEvidenceTargetId":"vocab_experience"}'::jsonb,'live'),
('u7_idea_confidence',7,'idea_set','{"originalIdea":"Regular practice gives candidates the confidence to speak clearly in an interview.","accurateParaphrases":["Practising often helps applicants to believe they can speak clearly at an interview.","Applicants who practise regularly feel sure of themselves when they have to speak clearly in front of a panel.","By rehearsing frequently, people attending the meeting come to trust their own ability to speak clearly."],"meaningInvariants":[{"type":"cause_effect","value":"regular practice gives belief in yourself"}],"distractors":[{"text":"Regular practice gives candidates the fear of speaking clearly in an interview.","misconceptionCategory":"polarity_change"},{"text":"Occasional practice gives candidates the confidence to speak clearly in an interview.","misconceptionCategory":"quantity_change"},{"text":"Regular practice gives candidates the confidence to write clearly in an interview.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_confidence_7"],"primaryEvidenceTargetId":"vocab_confidence_7"}'::jsonb,'live'),
('u7_idea_anxious',7,'idea_set','{"originalIdea":"Many candidates feel anxious before an interview, but most relax once they begin to speak.","accurateParaphrases":["A lot of applicants are nervous in advance of a job meeting, yet the majority calm down as soon as they start talking.","Before the meeting, plenty of candidates are worried, though most feel easier after they begin to speak.","Nerves affect many candidates beforehand, but the greater part settle down when they start to talk."],"meaningInvariants":[{"type":"time","value":"before ... once they begin"}],"distractors":[{"text":"Many candidates feel anxious after an interview, but most relax once they begin to speak.","misconceptionCategory":"time_change"},{"text":"Few candidates feel anxious before an interview, but most relax once they begin to speak.","misconceptionCategory":"quantity_change"},{"text":"Many candidates feel anxious before an interview, and most become more worried once they begin to speak.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_anxious_7"],"primaryEvidenceTargetId":"vocab_anxious_7"}'::jsonb,'live'),
('u7_idea_expertise',7,'idea_set','{"originalIdea":"The panel looked for candidates with expertise in teaching and in management.","accurateParaphrases":["The people choosing wanted applicants with a high level of knowledge about both teaching and managing.","Candidates who were skilled in teaching and also in managing were what the panel wanted.","Specialist knowledge of teaching and of management was what the interviewers were hoping to find."],"meaningInvariants":[{"type":"quantity","value":"both teaching and management"}],"distractors":[{"text":"The panel looked for candidates with expertise in teaching only.","misconceptionCategory":"omitted_information"},{"text":"The panel avoided candidates with expertise in teaching and in management.","misconceptionCategory":"polarity_change"},{"text":"The panel looked for candidates with a liking for teaching and for management.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_expertise"],"primaryEvidenceTargetId":"vocab_expertise"}'::jsonb,'live'),
('u7_idea_technique',7,'idea_set','{"originalIdea":"The coach taught the candidates a technique for staying calm during interviews.","accurateParaphrases":["The candidates were shown a method by their coach for keeping calm in an interview.","A way of staying relaxed in interviews was taught to the candidates by the coach.","The coach showed those attending a skilful method for remaining calm when being interviewed."],"meaningInvariants":[{"type":"cause_effect","value":"a technique for staying calm"}],"distractors":[{"text":"The coach taught the candidates a technique for becoming nervous during interviews.","misconceptionCategory":"polarity_change"},{"text":"The coach taught the candidates a technique for staying calm during exams.","misconceptionCategory":"meaning_confusion"},{"text":"The candidates taught the coach a technique for staying calm during interviews.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_technique_7"],"primaryEvidenceTargetId":"vocab_technique_7"}'::jsonb,'live'),
('u7_idea_evaluate',7,'idea_set','{"originalIdea":"The panel will evaluate each candidate against the same criteria.","accurateParaphrases":["Every candidate will be judged by the panel using identical standards.","The panel is going to assess all applicants by applying the very same measures.","Each of the people attending will be assessed by the panel according to one shared set of standards."],"meaningInvariants":[{"type":"comparison","value":"the same criteria"}],"distractors":[{"text":"The panel will evaluate each candidate against different criteria.","misconceptionCategory":"comparison_change"},{"text":"The panel will evaluate only some candidates against the same criteria.","misconceptionCategory":"quantity_change"},{"text":"The panel will announce each candidate against the same criteria.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_evaluate_7"],"primaryEvidenceTargetId":"vocab_evaluate_7"}'::jsonb,'live'),
('u7_idea_organise',7,'idea_set','{"originalIdea":"Students should organise their notes before they begin to revise.","accurateParaphrases":["Learners ought to put their notes in a sensible order prior to starting revision.","Before beginning revision, students are advised to arrange their notes carefully.","It is wise for those studying to sort out their notes before they start going over them."],"meaningInvariants":[{"type":"time","value":"before they begin to revise"}],"distractors":[{"text":"Students should organise their notes after they have finished revising.","misconceptionCategory":"time_change"},{"text":"Students should destroy their notes before they begin to revise.","misconceptionCategory":"polarity_change"},{"text":"Students should organise their friends before they begin to revise.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_organise"],"primaryEvidenceTargetId":"vocab_organise"}'::jsonb,'live'),
('u7_idea_distribute',7,'idea_set','{"originalIdea":"The manager will distribute the new rota to all staff on Monday.","accurateParaphrases":["The new rota will be given to every member of staff by the manager on Monday.","On Monday, the manager plans to hand the new rota out to all the workers.","All staff will receive the new rota from the manager at the start of the week."],"meaningInvariants":[{"type":"quantity","value":"all staff"}],"distractors":[{"text":"The manager will distribute the new rota to some staff on Monday.","misconceptionCategory":"quantity_change"},{"text":"The manager will distribute the new rota to all staff on Friday.","misconceptionCategory":"time_change"},{"text":"The manager will collect the new rota from all staff on Monday.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_distribute"],"primaryEvidenceTargetId":"vocab_distribute"}'::jsonb,'live'),
('u7_idea_allocate',7,'idea_set','{"originalIdea":"The school will allocate more time to speaking practice next year.","accurateParaphrases":["Next year, the school will set aside additional time for practice in speaking.","More lesson time will be given to speaking practice by the school in the coming year.","In the following year, the school will reserve a longer period for students to practise speaking."],"meaningInvariants":[{"type":"comparison","value":"more time"}],"distractors":[{"text":"The school will allocate less time to speaking practice next year.","misconceptionCategory":"comparison_change"},{"text":"The school allocated more time to speaking practice last year.","misconceptionCategory":"time_change"},{"text":"The school will allocate more time to writing practice next year.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_allocate"],"primaryEvidenceTargetId":"vocab_allocate"}'::jsonb,'live'),
('u7_idea_responsible',7,'idea_set','{"originalIdea":"Each team member is responsible for completing one part of the project.","accurateParaphrases":["Every person on the team has the duty to finish one section of the project.","The team is divided so that each member must complete a section of the project on their own.","One part of the project belongs to each member of the team, who must finish it."],"meaningInvariants":[{"type":"quantity","value":"each team member, one part"}],"distractors":[{"text":"Some team members are responsible for completing one part of the project.","misconceptionCategory":"quantity_change"},{"text":"Each team member is responsible for completing every part of the project.","misconceptionCategory":"quantity_change"},{"text":"Each team member is interested in completing one part of the project.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_responsible"],"primaryEvidenceTargetId":"vocab_responsible"}'::jsonb,'live'),
('u7_idea_editor',7,'idea_set','{"originalIdea":"The editor checked every article before the magazine was printed.","accurateParaphrases":["Before the magazine was printed, each article was read and checked by the person responsible for corrections.","All the articles were examined by the person in charge of the writing before printing.","Every piece in the magazine was looked over for mistakes before it went to print."],"meaningInvariants":[{"type":"quantity","value":"every article"}],"distractors":[{"text":"The editor checked some articles before the magazine was printed.","misconceptionCategory":"quantity_change"},{"text":"The editor checked every article after the magazine was printed.","misconceptionCategory":"time_change"},{"text":"The writer checked every article before the magazine was printed.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_editor"],"primaryEvidenceTargetId":"vocab_editor"}'::jsonb,'live'),
('u7_idea_proofread',7,'idea_set','{"originalIdea":"Candidates should proofread their application before they send it.","accurateParaphrases":["Applicants ought to check their application for mistakes prior to sending it.","Before an application is sent off, the person applying should read it through and correct errors.","It is advisable for those applying to look for errors in their forms before posting them."],"meaningInvariants":[{"type":"time","value":"before they send it"}],"distractors":[{"text":"Candidates should proofread their application after they send it.","misconceptionCategory":"time_change"},{"text":"Candidates should rewrite their application before they send it.","misconceptionCategory":"meaning_confusion"},{"text":"Candidates need not proofread their application before they send it.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_proofread"],"primaryEvidenceTargetId":"vocab_proofread"}'::jsonb,'live'),
('u7_idea_layout',7,'idea_set','{"originalIdea":"A clear layout makes a CV easier to read.","accurateParaphrases":["A CV is simpler to read when the items on the page are arranged clearly.","If the items are placed in an organised way, a CV becomes easier to read.","Readers find a CV easier to understand when the page is arranged in a tidy way."],"meaningInvariants":[{"type":"cause_effect","value":"a clear layout makes it easier"}],"distractors":[{"text":"A clear layout makes a CV harder to read.","misconceptionCategory":"polarity_change"},{"text":"A clear layout makes a CV longer to read.","misconceptionCategory":"degree_change"},{"text":"A clear layout makes a CV easier to write.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_layout"],"primaryEvidenceTargetId":"vocab_layout"}'::jsonb,'live'),
('u7_idea_visual',7,'idea_set','{"originalIdea":"Visual aids can help the audience to follow a presentation.","accurateParaphrases":["Pictures and diagrams can make it simpler for those listening to understand a talk.","Charts and images may help the listeners to keep up with the presentation.","A talk is easier for an audience to follow when things they can see are used."],"meaningInvariants":[{"type":"cause_effect","value":"help the audience follow"}],"distractors":[{"text":"Visual aids can prevent the audience from following a presentation.","misconceptionCategory":"polarity_change"},{"text":"Visual aids can help the speaker to follow a presentation.","misconceptionCategory":"meaning_confusion"},{"text":"Visual aids always help the audience to follow a presentation.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_visual"],"primaryEvidenceTargetId":"vocab_visual"}'::jsonb,'live'),
('u7_idea_criteria',7,'idea_set','{"originalIdea":"The panel judged every candidate according to the same criteria.","accurateParaphrases":["Each candidate was assessed by the panel using identical standards.","All of the people being interviewed were judged by the panel against one shared set of standards.","The panel applied exactly the same measures when assessing every applicant."],"meaningInvariants":[{"type":"comparison","value":"the same criteria"}],"distractors":[{"text":"The panel judged every candidate according to different criteria.","misconceptionCategory":"comparison_change"},{"text":"The panel judged only some candidates according to the same criteria.","misconceptionCategory":"quantity_change"},{"text":"The panel rewarded every candidate according to the same criteria.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_criteria_7"],"primaryEvidenceTargetId":"vocab_criteria_7"}'::jsonb,'live'),
('u7_idea_accurate',7,'idea_set','{"originalIdea":"Employers expect candidates to give accurate information on application forms.","accurateParaphrases":["Companies want applicants to put correct details on the forms they send in.","It is expected by employers that people applying will write exact and truthful details on forms.","Firms require that candidates fill in their application forms without errors."],"meaningInvariants":[{"type":"cause_effect","value":"expect"}],"distractors":[{"text":"Employers expect candidates to give brief information on application forms.","misconceptionCategory":"degree_change"},{"text":"Employers expect candidates to give accurate information in interviews.","misconceptionCategory":"meaning_confusion"},{"text":"Employers do not expect candidates to give accurate information on application forms.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_accurate"],"primaryEvidenceTargetId":"vocab_accurate"}'::jsonb,'live'),
('u7_idea_punctuation',7,'idea_set','{"originalIdea":"Poor punctuation can make a letter difficult to understand.","accurateParaphrases":["A letter can be hard to follow when the full stops and commas are used badly.","Using marks such as commas incorrectly may leave a letter confusing to read.","When commas and full stops are wrong, the reader can find a letter difficult to understand."],"meaningInvariants":[{"type":"cause_effect","value":"poor punctuation can make a letter difficult"}],"distractors":[{"text":"Good punctuation can make a letter difficult to understand.","misconceptionCategory":"polarity_change"},{"text":"Poor spelling can make a letter difficult to understand.","misconceptionCategory":"meaning_confusion"},{"text":"Poor punctuation always makes a letter impossible to understand.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_punctuation"],"primaryEvidenceTargetId":"vocab_punctuation"}'::jsonb,'live'),
